import pathlib,json
r={}
for line in pathlib.Path('/proc/self/cgroup').read_text().splitlines():
 if line.startswith('0::'):
  p=pathlib.Path('/sys/fs/cgroup')/line[3:].lstrip('/')
  while p!=pathlib.Path('/sys'):
   r[str(p)]={n:(p/n).read_text() if (p/n).is_file() else None for n in ('memory.events','memory.max','memory.current','cpu.max','cpuset.cpus.effective')}
   if p==pathlib.Path('/sys/fs/cgroup'):break
   p=p.parent
print(json.dumps(r))
